namespace Acme.Ticketing.Domain.Framework;

public interface IRepository<T> where T : Entity
{
    Task<T?> GetAsync(Guid id, CancellationToken ct = default);
    Task<Page<T>> QueryAsync(PageRequest request, CancellationToken ct = default);
    void Add(T entity);
    void Remove(T entity);
}

/// <summary>Nothing is saved until the unit of work commits.</summary>
public interface IUnitOfWork
{
    /// <summary>Saves the changes; a violated unique index or foreign key, or a concurrent change, is a conflict.</summary>
    Task<Result> CommitAsync(CancellationToken ct = default);
}
