using Acme.Ticketing.Domain.Framework;
using Microsoft.EntityFrameworkCore;

namespace Acme.Ticketing.Infrastructure.Framework;

public sealed class UnitOfWork(TicketingDbContext db) : IUnitOfWork
{
    public async Task<Result> CommitAsync(CancellationToken ct = default)
    {
        try
        {
            await db.SaveChangesAsync(ct);
            return Result.Success();
        }
        catch (DbUpdateConcurrencyException)
        {
            return Error.Conflict("The data was changed concurrently.");
        }
        catch (DbUpdateException e) when (IsConstraintViolation(e))
        {
            return Error.Conflict("The change violates a unique or reference constraint.");
        }
    }

    private static bool IsConstraintViolation(Exception e)
    {
        for (var inner = e.InnerException; inner is not null; inner = inner.InnerException)
            if (inner.Message.Contains("UNIQUE constraint failed") || inner.Message.Contains("FOREIGN KEY constraint failed"))
                return true;
        return false;
    }
}
