    public static IServiceCollection AddTicketingInfrastructure(
        this IServiceCollection services, Action<IServiceProvider, DbContextOptionsBuilder> configureDatabase)
    {
        services.AddDbContext<TicketingDbContext>(configureDatabase);
        services.AddScoped<IUnitOfWork, UnitOfWork>();
