    public static async Task InitializeTicketingDatabaseAsync(this IServiceProvider services)
    {
        await using var scope = services.CreateAsyncScope();
        await scope.ServiceProvider.GetRequiredService<TicketingDbContext>().Database.EnsureCreatedAsync();
    }
}
